import sys, math

def main():
    data = sys.stdin.buffer.read().split(b'\n')
    groups = {}
    for line in data[1:]:
        if not line:
            continue
        parts = line.rstrip(b'\r').split(b',')
        if len(parts) < 3:
            continue
        c = parts[1]
        v = float(parts[2])
        g = groups.get(c)
        if g is None:
            groups[c] = [v]
        else:
            g.append(v)
    out = []
    for c in sorted(groups):
        out.append(c.decode() + ',' + ('%.2f' % math.fsum(groups[c])))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()

import sys, math

def main():
    data = sys.stdin.buffer.read().split(b'\n')[1:]
    groups = {}
    get = groups.get
    for line in data:
        p = line.split(b',')
        if len(p) < 3:
            continue
        c = p[1]
        v = float(p[2])
        g = get(c)
        if g is None:
            groups[c] = [v]
        else:
            g.append(v)
    out = []
    for c in sorted(groups):
        out.append(c.decode() + ',' + ('%.2f' % math.fsum(groups[c])))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()
